let rec findUnique (nums : List Int) (h_precond : FindSingleNumber_precond (nums)) : Int :=
  let rec aux (acc : Int) (seen : Map Int Int) (remaining : List Int) : Int :=
    match remaining with
    | [] => acc
    | x :: xs =>
      let filtered :=
        List.filter (fun y => y = x) nums
      let count :=
        filtered.length
      let filtered_unique :=
        List.filter (fun y => y = x) xs
      let filtered_count :=
        filtered_unique.length
      if count = 1 then
        x
      else
        aux acc (seen.map (fun y => y + 1)) filtered_unique remaining
  aux 0 (Map.of 0 0) nums

