let n := nums.length
if n <= 1 then 0
else
  let isSorted (l : List Int) : Bool :=
    List.Pairwise (· ≤ ·) l

  -- Recursive function to find minimum right shifts
  let minShifts (n : Nat) (l : List Int) : Int :=
    if isSorted l then 0
    else
      let k := Nat.mod n (l.length)
      if k = 0 then n - 1
      else minShifts (k + 1) (rotateRight k l)

  minShifts n nums

