  fun x _ _ =>
    if x = 1 then 1
    else
      let i2 := if x = 1 then 1 else go k (x * 2) x (x - 1)
      let i3 := if x = 1 then 1 else go k (x * 3) x (x - 1)
      let i5 := if x = 1 then 1 else go k (x * 5) x (x - 1)
      let next := min (min (i2 * 2) (i3 * 3)) (i5 * 5)
